const BRAND = "TripleZero iT";

function p(...paras: string[]) {
  return paras.map((t) => `<p>${t}</p>`).join("\n");
}
function h2(t: string) {
  return `<h2>${t}</h2>`;
}
function ol(items: string[]) {
  return `<ol>\n${items.map((i) => `  <li>${i}</li>`).join("\n")}\n</ol>`;
}
function ul(items: string[]) {
  return `<ul>\n${items.map((i) => `  <li>${i}</li>`).join("\n")}\n</ul>`;
}
function tip(t: string) {
  return `<aside class="kb-callout kb-callout-tip"><p><strong>Tip:</strong> ${t}</p></aside>`;
}
function warn(t: string) {
  return `<aside class="kb-callout kb-callout-warn"><p><strong>Let op:</strong> ${t}</p></aside>`;
}
function outro(related?: string) {
  return p(
    `Heb je na het volgen van deze stappen nog vragen? Neem contact op met ${BRAND} support via het ticketssysteem of plan een afspraak.`,
    related
      ? `Gerelateerd: ${related}`
      : `Bekijk ook andere artikelen over webdesign, Next.js en onderhoud.`,
  );
}

type Ctx = { title: string; topic: string };

type Spec = {
  lead: string;
  why: string[];
  steps: string[];
  pitfalls: string[];
  tip: string;
  warn: string;
  related: string;
};

function howto(title: string, spec: Spec): string {
  return [
    p(spec.lead, `We schrijven vanuit de praktijk bij ${BRAND}: hosting, VPS, control panels en trajecten die bij jouw pakket passen.`),
    h2("Waarom dit belangrijk is"),
    ul(spec.why),
    h2(`Stappenplan: ${title}`),
    ol(spec.steps),
    h2("Veelgemaakte fouten"),
    ul(spec.pitfalls),
    tip(spec.tip),
    warn(spec.warn),
    outro(spec.related),
  ].join("\n");
}

